### 2.1 Express

Express is a minimal, unopinionated HTTP framework. It is suitable for services with:
- Simple to moderate request routing requirements.
- Teams already familiar with the Express middleware model.
- Existing codebases being migrated to TypeScript.

**Mandatory security configuration for Express:**

```typescript
// src/app.ts
import express, { Application } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import pinoHttp from 'pino-http';
import { correlationIdMiddleware } from './api/middleware/correlation-id.middleware';
import { authMiddleware } from './api/middleware/auth.middleware';
import { errorHandlerMiddleware } from './api/middleware/error-handler.middleware';
import { membersRouter } from './api/routes/members.router';
import { healthRouter } from './api/routes/health.router';
import { logger } from './utils/logger';
import { config } from './config';

export function createApp(): Application {
  const app = express();

  // 1. Security headers — must be first
  app.use(
    helmet({
      contentSecurityPolicy: {
        directives: { defaultSrc: ["'none'"], scriptSrc: ["'self'"], connectSrc: ["'self'"] },
      },
      hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
      referrerPolicy: { policy: 'no-referrer' },
    })
  );

  // 2. CORS — explicit allow-list
  const allowedOrigins = config.CORS_ALLOWED_ORIGINS
    ? config.CORS_ALLOWED_ORIGINS.split(',').map((o) => o.trim())
    : [];
  app.use(
    cors({
      origin: (origin, cb) => {
        if (!origin || allowedOrigins.includes(origin)) return cb(null, true);
        cb(new Error(`CORS: origin '${origin}' not permitted`));
      },
      methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
      allowedHeaders: ['Content-Type', 'Authorization', 'X-Correlation-ID'],
      credentials: true,
    })
  );

  // 3. Rate limiting
  app.use(
    '/api/',
    rateLimit({ windowMs: 15 * 60 * 1000, max: 200, standardHeaders: true, legacyHeaders: false })
  );

  // 4. Request parsing with prototype pollution mitigation
  app.use(
    express.json({
      limit: '1mb',
      reviver: (key, value) =>
        key === '__proto__' || key === 'constructor' ? undefined : value,
    })
  );

  // 5. Correlation ID
  app.use(correlationIdMiddleware);

  // 6. Structured request logging
  app.use(pinoHttp({ logger, genReqId: (req) => req.correlationId }));

  // 7. Health (unauthenticated)
  app.use('/health', healthRouter);

  // 8. Authentication
  app.use('/api/', authMiddleware);

  // 9. Routes
  app.use('/api/members', membersRouter);

  // 10. Error handler — must be last
  app.use(errorHandlerMiddleware);

  return app;
}
```

