### 2.2 Fastify

Fastify is suitable for services where request throughput is a primary concern. It has a plugin architecture that differs from Express middleware chains.

**Mandatory security configuration for Fastify:**

```typescript
// src/app.ts
import Fastify, { FastifyInstance } from 'fastify';
import fastifyHelmet from '@fastify/helmet';
import fastifyCors from '@fastify/cors';
import fastifyRateLimit from '@fastify/rate-limit';
import { config } from './config';

export async function createApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: false, // Use pino directly; disable Fastify's built-in logger to control config
    disableRequestLogging: true,
  });

  await app.register(fastifyHelmet, {
    contentSecurityPolicy: {
      directives: { defaultSrc: ["'none'"], connectSrc: ["'self'"] },
    },
  });

  await app.register(fastifyCors, {
    origin: config.CORS_ALLOWED_ORIGINS.split(',').map((o) => o.trim()),
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    credentials: true,
  });

  await app.register(fastifyRateLimit, {
    max: 200,
    timeWindow: '15 minutes',
    skipOnError: false,
    // Health and readiness probes must be excluded from rate limiting. Register health
    // routes with { config: { rateLimit: false } } in the route schema to ensure
    // Kubernetes liveness/readiness probes are never throttled regardless of traffic load.
  });

  // Fastify validates JSON Schema natively — configure schemas on each route
  // to achieve the same input validation as Zod in Express

  return app;
}
```

