### 4.1 JWT Authentication ([PTN-SEC-API-002](../../../../patterns/security/api-microservices/PTN-SEC-API-002-jwt-token-pattern.md))

The JWT Token Pattern requires signature verification against a JWKS endpoint. Use `jsonwebtoken` for token verification and `jwks-rsa` to fetch the signing key from the identity provider's JWKS endpoint.

```typescript
// src/api/middleware/auth.middleware.ts
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import jwksRsa, { JwksClient } from 'jwks-rsa';
import { config } from '../../config';
import { logger } from '../../utils/logger';

const jwksClient: JwksClient = jwksRsa({
  jwksUri: config.JWKS_URI,
  cache: true,
  cacheMaxEntries: 10,
  cacheMaxAge: 10 * 60 * 1000,
  rateLimit: true,
  jwksRequestsPerMinute: 10,
});

function getSigningKey(kid: string): Promise<string> {
  return new Promise((resolve, reject) => {
    jwksClient.getSigningKey(kid, (err, key) => {
      if (err || !key) return reject(err ?? new Error('No signing key found'));
      resolve(key.getPublicKey());
    });
  });
}

export interface AuthenticatedRequest extends Request {
  jwtPayload: jwt.JwtPayload;
}

export function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    res.status(401).json({ error: { code: 'UNAUTHORISED', message: 'Missing or invalid Authorization header' } });
    return;
  }

  const token = authHeader.slice(7);

  let decoded: jwt.Jwt | null;
  try {
    decoded = jwt.decode(token, { complete: true });
  } catch {
    res.status(401).json({ error: { code: 'UNAUTHORISED', message: 'Malformed JWT' } });
    return;
  }

  if (!decoded?.header.kid) {
    res.status(401).json({ error: { code: 'UNAUTHORISED', message: 'JWT missing kid header' } });
    return;
  }

  const kid = decoded.header.kid;

  getSigningKey(kid)
    .then((signingKey) => {
      jwt.verify(
        token,
        signingKey,
        {
          algorithms: ['RS256'],
          audience: config.JWT_AUDIENCE,
          issuer: config.JWT_ISSUER,
        },
        (err, payload) => {
          if (err || !payload || typeof payload === 'string') {
            logger.warn({ err, correlationId: req.correlationId }, 'JWT verification failed');
            res.status(401).json({ error: { code: 'UNAUTHORISED', message: 'Invalid or expired token' } });
            return;
          }
          (req as AuthenticatedRequest).jwtPayload = payload;
          next();
        }
      );
    })
    .catch((err: unknown) => {
      logger.error({ err, correlationId: req.correlationId }, 'JWKS key fetch failed');
      res.status(500).json({ error: { code: 'INTERNAL_ERROR', message: 'Authentication service unavailable' } });
    });
}
```

**Key implementation notes:**
- Always verify `audience` and `issuer` claims. Omitting either allows tokens issued for another service or by another IdP to be accepted.
- Cache JWKS responses (`cache: true`). The JWKS endpoint has rate limits; fetching on every request will eventually be throttled.
- Only `RS256` (asymmetric) is accepted. Symmetric `HS256` is not acceptable because it requires sharing a secret between the IdP and every service.
- Set `jwksRequestsPerMinute` proportional to expected deployment concurrency. For services with more than five replicas or rolling deployments, consider increasing to 30–50 and coordinating with the IAM team on IdP JWKS endpoint capacity. The `cacheMaxAge: 600_000` (10 min) mitigates this for steady-state traffic; the burst concern is at cold start.

