### 4.2 OAuth2 Authorization ([PTN-SEC-API-005](../../../../patterns/security/api-microservices/PTN-SEC-API-005-oauth2-authorization-pattern.md))

For services that act as OAuth2 resource servers (validating bearer tokens from a client), the pattern above (§4.1) covers token validation. For services that need to acquire tokens on behalf of users (OIDC/Authorization Code flow), use `express-openid-connect`:

```typescript
// src/app.ts — OIDC/Authorization Code Flow (BFF or portal services only)
import { auth, requiresAuth } from 'express-openid-connect';

app.use(
  auth({
    authRequired: false,
    auth0Logout: true,
    baseURL: config.BASE_URL,
    clientID: config.OIDC_CLIENT_ID,
    issuerBaseURL: config.OIDC_ISSUER_URL,
    secret: config.SESSION_SECRET,
    routes: {
      callback: '/auth/callback',
      login: '/auth/login',
      logout: '/auth/logout',
    },
  })
);

// Protect specific routes
router.get('/dashboard', requiresAuth(), dashboardController.get);
```

For machine-to-machine (M2M) token acquisition (service-to-service), use the OAuth2 `client_credentials` grant. The `client_secret` **must** be retrieved from AWS Secrets Manager or HashiCorp Vault at startup per [PTN-SEC-API-008](../../../../patterns/security/api-microservices/PTN-SEC-API-008-secret-management-pattern.md). It must not be stored in environment variables, Kubernetes secret YAML committed to source control, or Helm values files.

```typescript
// src/server.ts — bootstrap: fetch secrets once at startup
import { getSecret } from './infrastructure/secrets/aws-secrets.client';
import { createApp } from './app';

// Separate mutable runtime secrets holder — not frozen.
// The config object (config.ts) is Object.freeze()d per STD-TEC-NODE-001 §5.1;
// secrets that arrive at runtime must be held outside the frozen config singleton.
export const runtimeSecrets: Record<string, string> = {};

async function bootstrap(): Promise<void> {
  // Populate the runtime secrets holder before constructing the app.
  runtimeSecrets.OAUTH_CLIENT_SECRET = await getSecret('prod/service-name/oauth-client-secret');

  const app = createApp();
  // ... server.listen
}

bootstrap().catch((err) => {
  console.error('Bootstrap failed:', err);
  process.exit(1);
});
```

```typescript
// src/infrastructure/http/token.client.ts
import { config } from '../../config';
import { runtimeSecrets } from '../../server';

interface TokenResponse {
  access_token: string;
  expires_in: number;
  token_type: string;
}

export async function fetchClientCredentialsToken(scope: string): Promise<string> {
  const params = new URLSearchParams({
    grant_type: 'client_credentials',
    client_id: config.OAUTH_CLIENT_ID,
    client_secret: runtimeSecrets.OAUTH_CLIENT_SECRET, // populated at bootstrap from Secrets Manager
    scope,
  });

  const response = await fetch(`${config.OAUTH_TOKEN_URL}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
    signal: AbortSignal.timeout(5000),
  });

  if (!response.ok) {
    throw new Error(`Token request failed: ${response.status}`);
  }

  const data = (await response.json()) as TokenResponse;
  return data.access_token;
}
```

