### 4.3 Secrets Management ([PTN-SEC-API-008](../../../../patterns/security/api-microservices/PTN-SEC-API-008-secret-management-pattern.md))

Secrets (database passwords, API keys, OAuth client secrets) must never be hardcoded or stored in environment variable files committed to source control. Use either HashiCorp Vault or AWS Secrets Manager depending on the deployment platform.

**AWS Secrets Manager client (for AWS-deployed services):**

```typescript
// src/infrastructure/secrets/aws-secrets.client.ts
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';

const client = new SecretsManagerClient({ region: process.env.AWS_REGION ?? 'us-east-1' });

const secretCache = new Map<string, { value: string; expiresAt: number }>();
const CACHE_TTL_MS = 5 * 60 * 1000;

export async function getSecret(secretName: string): Promise<string> {
  const cached = secretCache.get(secretName);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.value;
  }

  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  const secretValue = response.SecretString;
  if (!secretValue) throw new Error(`Secret '${secretName}' has no string value`);

  secretCache.set(secretName, { value: secretValue, expiresAt: Date.now() + CACHE_TTL_MS });
  return secretValue;
}
```

**HashiCorp Vault client (for on-premises or multi-cloud services):**

```typescript
// src/infrastructure/secrets/vault.client.ts
import nodeVault from 'node-vault';

const vault = nodeVault({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR ?? 'https://vault.internal:8200',
  token: process.env.VAULT_TOKEN,
});

export async function getVaultSecret(path: string, key: string): Promise<string> {
  const result = (await vault.read(path)) as { data: { data: Record<string, string> } };
  const value = result.data.data[key];
  if (!value) throw new Error(`Vault secret at '${path}' does not contain key '${key}'`);
  return value;
}
```

**Integration at startup:**

Secrets should be fetched at service startup and injected into the configuration object — not fetched on every request:

```typescript
// src/server.ts
import { getSecret } from './infrastructure/secrets/aws-secrets.client';
import { createApp } from './app';

async function bootstrap(): Promise<void> {
  const dbPassword = await getSecret('prod/member-service/db-password');
  process.env.DB_PASSWORD = dbPassword;

  const app = createApp();
  // ... server.listen
}

bootstrap().catch((err) => {
  console.error('Bootstrap failed:', err);
  process.exit(1);
});
```

