## 6. Middleware Stack Implementation

The correct middleware registration order is critical for security. Registering security middleware after route handlers or body parsers leaves the application in an unprotected state during startup.

The required order for Express services:

```typescript
// src/app.ts — complete middleware registration order
import express from 'express';
import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import pinoHttp from 'pino-http';
import { correlationIdMiddleware } from './api/middleware/correlation-id.middleware';
import { authMiddleware } from './api/middleware/auth.middleware';
import { errorHandlerMiddleware } from './api/middleware/error-handler.middleware';
import { healthRouter } from './api/routes/health.router';
import { membersRouter } from './api/routes/members.router';
import { logger } from './utils/logger';
import { config } from './config';

export function createApp(): express.Application {
  const app = express();

  // Step 1: Security headers (no authentication required — applies to all responses)
  app.use(helmet({ hsts: { maxAge: 31536000, includeSubDomains: true } }));

  // Step 2: CORS preflight handling
  app.use(cors({ origin: config.CORS_ALLOWED_ORIGINS.split(','), credentials: true }));

  // Step 3: Rate limiting (health check endpoints are explicitly exempt per STD-TEC-NODE-001 §3.3)
  app.use(
    '/api/',
    rateLimit({
      windowMs: 900_000,
      max: 200,
      skip: (req) => req.path === '/health' || req.path === '/ready',
    })
  );

  // Step 4: Body parsing with prototype pollution guard
  app.use(
    express.json({
      limit: '1mb',
      reviver: (key, val) => (key === '__proto__' || key === 'constructor' ? undefined : val),
    })
  );

  // Step 5: Correlation ID (must be before logging so logs include it)
  app.use(correlationIdMiddleware);

  // Step 6: Request logging
  app.use(pinoHttp({ logger, genReqId: (req) => req.correlationId }));

  // Step 7: Health check (unauthenticated — must be before auth middleware)
  app.use('/health', healthRouter);

  // Step 8: Authentication (applied to all /api/ routes)
  app.use('/api/', authMiddleware);

  // Step 9: Business routes
  app.use('/api/members', membersRouter);

  // Step 10: Error handler (must be last — 4-argument signature required)
  app.use(errorHandlerMiddleware);

  return app;
}
```

